#include <bits/stdc++.h>
using namespace std;

const int Maxn = 1 << 19 | 5;
int n, k, p, maxi, pop[Maxn], f[Maxn];
int a1[20][Maxn], a2[20][Maxn], a3[20][Maxn];
long long pp;
long long tmp[20][Maxn];
long long fact[Maxn], inv_fact[Maxn];

long long power(long long x, long long y) {
    long long res = 1, cur = x;
    while (y) {
        if (y & 1) res = res * cur % p;
        cur = cur * cur % p;
        y >>= 1;
    }
    return res;
}

void precompute() {
    fact[0] = 1;
    for (int i = 1; i <= maxi; i++)
        fact[i] = fact[i - 1] * i % p;
    inv_fact[maxi] = power(fact[maxi], p - 2);
    for (int i = maxi - 1; i >= 0; i--)
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % p;
}

int next_pow2(int x) {
    int t = 1;
    while (t < x) t <<= 1;
    return t;
}

void fwt(int *arr, int len, bool inv = false) {
    long long *buf = tmp[0];
    for (int i = 0; i < len; i++) buf[i] = arr[i];
    if (inv) {
        for (int step = 1; step < len; step <<= 1)
            for (int i = 0; i < len; i += (step << 1))
                for (int j = i; j < i + step; j++)
                    buf[j + step] -= buf[j];
    } else {
        for (int step = 1; step < len; step <<= 1)
            for (int i = 0; i < len; i += (step << 1))
                for (int j = i; j < i + step; j++)
                    buf[j + step] += buf[j];
    }
    for (int i = 0; i < len; i++) {
        arr[i] = buf[i] % p;
        if (arr[i] < 0) arr[i] += p;
    }
}

inline void reduce(long long &x) { if (x >= pp) x -= pp; }

void multiply() {
    for (int i = 0; i <= 19; i++) {
        memset(a1[i], 0, sizeof(int[maxi + 1]));
        memset(tmp[i], 0, sizeof(long long[maxi + 1]));
    }
    for (int i = 0; i <= maxi; i++)
        a1[pop[i]][i] = f[i];
    for (int i = 0; i <= 19; i++)
        fwt(a1[i], maxi + 1);
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= maxi; s++)
                reduce(tmp[q + l][s] += 1LL * a1[q][s] * a2[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= maxi; s++)
            a3[q][s] = tmp[q][s] % p;
    for (int i = 0; i <= 19; i++)
        fwt(a3[i], maxi + 1, true);
    for (int i = 0; i <= maxi; i++)
        f[i] = a3[pop[i]][i];
}

void square() {
    static int temp[20][Maxn];
    for (int i = 0; i <= 19; i++)
        memset(tmp[i], 0, sizeof(long long[maxi + 1]));
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= maxi; s++)
                reduce(tmp[q + l][s] += 1LL * a2[q][s] * a2[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= maxi; s++)
            temp[q][s] = tmp[q][s] % p;
    for (int i = 0; i <= 19; i++)
        fwt(temp[i], maxi + 1, true);
    for (int i = 0; i <= 19; i++)
        memset(a2[i], 0, sizeof(int[maxi + 1]));
    for (int i = 0; i <= maxi; i++)
        a2[pop[i]][i] = temp[pop[i]][i];
    for (int i = 0; i <= 19; i++)
        fwt(a2[i], maxi + 1);
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    pp = 1LL * p * p;
    if (n & 1) {
        printf("%lld", power(k, n));
        return 0;
    }
    f[0] = 1;
    maxi = next_pow2(n + 1) - 1;
    precompute();
    for (int i = 0; i <= maxi; i++)
        pop[i] = __builtin_popcount(i);
    for (int i = 0; i <= maxi; i++)
        a2[pop[i]][i] = inv_fact[i];
    for (int i = 0; i <= 19; i++)
        fwt(a2[i], maxi + 1);
    int orig_k = k;
    while (k) {
        if (k & 1) multiply();
        k >>= 1;
        if (k) square();
    }
    long long ans = (power(orig_k, n) - fact[n] * 1LL * f[n] % p + p) % p;
    printf("%lld", ans);
    return 0;
}
