import java.util.Scanner;

public class Main {
    static final int Maxn = (1 << 19) | 5;
    static int n, k, p, maxi;
    static int[] pop = new int[Maxn];
    static int[] f = new int[Maxn];
    static int[][] a1 = new int[20][Maxn];
    static int[][] a2 = new int[20][Maxn];
    static int[][] a3 = new int[20][Maxn];
    static long pp;
    static long[][] tmp = new long[20][Maxn];
    static long[] fact = new long[Maxn];
    static long[] inv_fact = new long[Maxn];

    static long power(long x, long y) {
        long res = 1, cur = x;
        while (y > 0) {
            if ((y & 1) == 1) res = res * cur % p;
            cur = cur * cur % p;
            y >>= 1;
        }
        return res;
    }

    static void precompute() {
        fact[0] = 1;
        for (int i = 1; i <= maxi; i++)
            fact[i] = fact[i - 1] * i % p;
        inv_fact[maxi] = power(fact[maxi], p - 2);
        for (int i = maxi - 1; i >= 0; i--)
            inv_fact[i] = inv_fact[i + 1] * (i + 1) % p;
    }

    static int next_pow2(int x) {
        int t = 1;
        while (t < x) t <<= 1;
        return t;
    }

    static void fwt(int[] arr, int len, boolean inv) {
        long[] buf = tmp[0];
        for (int i = 0; i < len; i++) buf[i] = arr[i];
        if (inv) {
            for (int step = 1; step < len; step <<= 1)
                for (int i = 0; i < len; i += (step << 1))
                    for (int j = i; j < i + step; j++)
                        buf[j + step] -= buf[j];
        } else {
            for (int step = 1; step < len; step <<= 1)
                for (int i = 0; i < len; i += (step << 1))
                    for (int j = i; j < i + step; j++)
                        buf[j + step] += buf[j];
        }
        for (int i = 0; i < len; i++) {
            arr[i] = (int)(buf[i] % p);
            if (arr[i] < 0) arr[i] += p;
        }
    }

    static void reduce(long[] x, int idx) {
        if (x[idx] >= pp) x[idx] -= pp;
    }

    static void multiply() {
        for (int i = 0; i <= 19; i++) {
            java.util.Arrays.fill(a1[i], 0, maxi + 1, 0);
            java.util.Arrays.fill(tmp[i], 0, maxi + 1, 0L);
        }
        for (int i = 0; i <= maxi; i++)
            a1[pop[i]][i] = f[i];
        for (int i = 0; i <= 19; i++)
            fwt(a1[i], maxi + 1, false);
        for (int q = 0; q <= 19; q++)
            for (int l = 0; q + l <= 19; l++)
                for (int s = 0; s <= maxi; s++)
                    reduce(tmp[q + l], s, (long)a1[q][s] * a2[l][s]);
        for (int q = 0; q <= 19; q++)
            for (int s = 0; s <= maxi; s++)
                a3[q][s] = (int)(tmp[q][s] % p);
        for (int i = 0; i <= 19; i++)
            fwt(a3[i], maxi + 1, true);
        for (int i = 0; i <= maxi; i++)
            f[i] = a3[pop[i]][i];
    }

    static void reduce(long[] arr, int idx, long add) {
        arr[idx] += add;
        if (arr[idx] >= pp) arr[idx] -= pp;
    }

    static void square() {
        int[][] temp = new int[20][Maxn];
        for (int i = 0; i <= 19; i++)
            java.util.Arrays.fill(tmp[i], 0, maxi + 1, 0L);
        for (int q = 0; q <= 19; q++)
            for (int l = 0; q + l <= 19; l++)
                for (int s = 0; s <= maxi; s++)
                    reduce(tmp[q + l], s, (long)a2[q][s] * a2[l][s]);
        for (int q = 0; q <= 19; q++)
            for (int s = 0; s <= maxi; s++)
                temp[q][s] = (int)(tmp[q][s] % p);
        for (int i = 0; i <= 19; i++)
            fwt(temp[i], maxi + 1, true);
        for (int i = 0; i <= 19; i++)
            java.util.Arrays.fill(a2[i], 0, maxi + 1, 0);
        for (int i = 0; i <= maxi; i++)
            a2[pop[i]][i] = temp[pop[i]][i];
        for (int i = 0; i <= 19; i++)
            fwt(a2[i], maxi + 1, false);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        p = sc.nextInt();
        pp = (long)p * p;
        if ((n & 1) == 1) {
            System.out.println(power(k, n));
            return;
        }
        f[0] = 1;
        maxi = next_pow2(n + 1) - 1;
        precompute();
        for (int i = 0; i <= maxi; i++)
            pop[i] = Integer.bitCount(i);
        for (int i = 0; i <= maxi; i++)
            a2[pop[i]][i] = (int)inv_fact[i];
        for (int i = 0; i <= 19; i++)
            fwt(a2[i], maxi + 1, false);
        int orig_k = k;
        while (k > 0) {
            if ((k & 1) == 1) multiply();
            k >>= 1;
            if (k > 0) square();
        }
        long ans = (power(orig_k, n) - fact[n] * (long)f[n] % p + p) % p;
        System.out.println(ans);
        sc.close();
    }
}
